async function loadPlan(){
  clearError();
  try{
    // Load project catalog for sourceUrls
    const projRes = await fetch(CLASSICS_DATA_FILES.libraryCatalog, { cache:"no-store" });
    if (!projRes.ok) throw new Error(`Could not load library.json (${projRes.status})`);
    const projectData = await projRes.json();
    if (!Array.isArray(projectData)) throw new Error("library.json must be an array");
    state.projectCatalog = projectData;

    state.readingGuideRows = await loadReadingGuides();
    state.readingGuideLookup = buildReadingGuideLookup(state.readingGuideRows);

    // Load reading plan
    const res = await fetch(CLASSICS_DATA_FILES.readingPlan, { cache:"no-store" });
    if (!res.ok) throw new Error(`Could not load bookclub.json (${res.status})`);
    const data = await res.json();
    if (!data || !Array.isArray(data.years)) throw new Error("bookclub.json must include { plan_name, years: [...] }");

    state.plan = data;

    const today = new Date().toLocaleDateString(undefined, { weekday:"long", year:"numeric", month:"long", day:"numeric" });
    $("#today").textContent = today;

    flattenPlan();
    buildLibraryWorks();
    buildGreatIdeasUniverse();
    fillYearOptions();
    buildTagsUniverse();
    wireUI();
    renderAll();
  } catch(err){
    setError(`LOAD ERROR: ${err.message}`);
  }
}

async function loadReadingGuides(){
  try{
    const res = await fetch(CLASSICS_DATA_FILES.readingGuide, { cache:"no-store" });
    if (!res.ok) throw new Error(`Could not load greatbooks.csv (${res.status})`);
    const text = await res.text();
    return parseCsvRecords(text);
  } catch(err){
    console.warn("Reading guidance CSV unavailable:", err);
    return [];
  }
}

async function loadGlossaryTerms(){
  if (glossaryState.terms.length || glossaryState.loading) return;
  glossaryState.loading = true;
  glossaryState.error = "";
  renderGlossary();
  try {
    const results = await Promise.allSettled(
      TERMS_URLS.map(url => fetch(url, { cache:"no-store" }).then(r => r.ok ? r.json() : null))
    );
    const allRaw = [];
    for (const result of results) {
      if (result.status === "fulfilled" && result.value) allRaw.push(...getRawTermsPayload(result.value));
    }
    if (!allRaw.length) throw new Error("No glossary data could be loaded.");
    glossaryState.terms = allRaw.map(normalizeTerm).sort((a,b) =>
      a.letter.localeCompare(b.letter) || a.term.localeCompare(b.term, undefined, { sensitivity:"base" })
    );
    applyGlossaryFilters();
  } catch(err){
    glossaryState.error = err.message || String(err);
  } finally {
    glossaryState.loading = false;
    renderGlossary();
  }
}

async function loadBookDetails(section){
  const author = section.dataset.author || "";
  const title  = section.dataset.title  || "";
  const inner  = section.querySelector(".bookDetailsPanel > div");
  if (!inner) return;

  // Prevent duplicate in-flight fetches for the same section
  if (inner._loadingDetails) return;
  inner._loadingDetails = true;

  inner.innerHTML = `<div class="bookDetailsLoading">Loading…</div>`;

  if (remoteBookEnrichmentShouldStayLocal()) {
    inner.innerHTML = remoteBookEnrichmentUnavailableHtml();
    inner._loadingDetails = false;
    return;
  }

  try {
    // Fetch all three sources in parallel for faster load
    const [olResult, gutResult, wikiResult] = await Promise.allSettled([
      _fetchOpenLibrary(title, author),
      _fetchGutendexDetails(title, author),
      _fetchWikipediaDetails(title, author)
    ]);

    const sources = [];
    if (olResult.status === "fulfilled" && olResult.value){
      sources.push({ label: "Open Library", html: _renderBookDetailsResult(olResult.value) });
    }
    if (gutResult.status === "fulfilled" && gutResult.value){
      sources.push({ label: "Project Gutenberg", html: _renderGutendexResult(gutResult.value) });
    }
    if (wikiResult.status === "fulfilled" && wikiResult.value){
      sources.push({ label: "Wikipedia", html: _renderWikipediaResult(wikiResult.value) });
    }

    if (!sources.length){
      inner.innerHTML = remoteBookEnrichmentUnavailableHtml("Remote book sources returned no details. Your local notes and outside search links still work.");
      return;
    }

    // Store sources on the inner element (cleared when card is closed)
    inner._sources = sources;
    inner._sourceIdx = 0;
    _renderSourceView(inner);
  } catch(err){
    inner.innerHTML = remoteBookEnrichmentUnavailableHtml();
  } finally {
    inner._loadingDetails = false;
  }
}

async function _fetchOpenLibrary(title, author){
  const fields = "key,title,author_name,first_publish_year,subject,subject_time_period,cover_i,number_of_pages_median,edition_count";
  const url = `https://openlibrary.org/search.json?title=${encodeURIComponent(title)}&author=${encodeURIComponent(author)}&limit=3&fields=${fields}`;
  const res = await fetch(url);
  if (!res.ok) return null;
  const data = await res.json();
  const docs = data.docs || [];
  if (!docs.length) return null;
  const normTitle = normalizeText(title);
  return docs.find(d => normalizeText(d.title || "") === normTitle) || docs[0] || null;
}

async function _fetchGutendexDetails(title, author){
  const q = [title, author].filter(Boolean).join(" ");
  const url = `https://gutendex.com/books/?search=${encodeURIComponent(q)}`;
  const res = await fetch(url);
  if (!res.ok) return null;
  const data = await res.json();
  const results = data.results || [];
  if (!results.length) return null;
  const normTitle = normalizeText(title);
  return results.find(b => normalizeText(b.title || "") === normTitle) || results[0];
}

async function _fetchWikipediaDetails(title, author){
  const q = [title, author].filter(Boolean).join(" ");
  const searchUrl = `https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(q)}&srlimit=3&format=json&origin=*`;
  const searchRes = await fetch(searchUrl);
  if (!searchRes.ok) return null;
  const searchData = await searchRes.json();
  const hits = searchData.query?.search || [];
  if (!hits.length) return null;
  const pageTitle = hits[0].title;
  const summaryRes = await fetch(`https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(pageTitle)}`);
  if (!summaryRes.ok) return null;
  return summaryRes.json();
}

async function loadDictionaryForSelectedTerm(){
  const term = glossaryState.selectedTerm;
  if (!term || PAGES[glossaryState.pageIndex] !== "dictionary") return;
  const keys = dictionaryLookupKeys(term);
  if (keys.some(k => glossaryState.dictionaryCache[k.toLowerCase()])) return;
  const unavailable = glossaryRemoteEnrichmentUnavailableReason("Dictionary");
  if (unavailable) { glossaryState.dictionaryRemoteUnavailable[keys[0].toLowerCase()] = unavailable; renderTermModal(); return; }
  let serviceUnavailable = "";
  for (const key of keys){
    const cacheKey = key.toLowerCase();
    try {
      const response = await fetch(`https://api.dictionaryapi.dev/api/v2/entries/en/${encodeURIComponent(key)}`);
      if (!response.ok) continue;
      const data = await response.json();
      const entries = Array.isArray(data) ? data : [];
      const hasDefinitions = entries.some(entry => (entry.meanings || []).some(meaning => (meaning.definitions || []).some(def => def.definition)));
      if (hasDefinitions) {
        glossaryState.dictionaryCache[cacheKey] = { word: entries[0]?.word || key, entries: entries.map(entry => ({ word: entry.word || key, phonetic: entry.phonetic || "", meanings: (entry.meanings || []).map(meaning => ({ partOfSpeech: meaning.partOfSpeech || "", definitions: (meaning.definitions || []).map(def => ({ definition: def.definition || "", example: def.example || "", synonyms: Array.isArray(def.synonyms) ? def.synonyms : [] })) })) })) };
        saveDictionaryCache();
        renderTermModal();
        return;
      }
    } catch(e){
      serviceUnavailable = "Dictionary service unavailable: remote lookup failed. References, idea map, and related library still work.";
    }
  }
  if (serviceUnavailable) {
    glossaryState.dictionaryRemoteUnavailable[keys[0].toLowerCase()] = serviceUnavailable;
    renderTermModal();
    return;
  }
  glossaryState.dictionaryCache[keys[0].toLowerCase()] = { error:true };
  saveDictionaryCache();
  renderTermModal();
}

async function loadWikipediaForSelectedTerm(){
  const term = glossaryState.selectedTerm;
  if (!term || PAGES[glossaryState.pageIndex] !== "wikipedia") return;
  const keys = wikipediaLookupKeys(term);
  if (keys.some(k => glossaryState.wikipediaCache[k.toLowerCase()])) return;
  const unavailable = glossaryRemoteEnrichmentUnavailableReason("Wikipedia");
  if (unavailable) { glossaryState.wikipediaRemoteUnavailable[keys[0].toLowerCase()] = unavailable; renderTermModal(); return; }
  let serviceUnavailable = "";
  for (const key of keys){
    const cacheKey = key.toLowerCase();
    try {
      const response = await fetch(`https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(key)}`);
      if (!response.ok) continue;
      const data = await response.json();
      if (data?.extract) {
        glossaryState.wikipediaCache[cacheKey] = { title: data.title || key, extract: data.extract, url: data.content_urls?.desktop?.page || data.content_urls?.mobile?.page || "", thumbnail: data.thumbnail?.source || "" };
        saveWikipediaCache();
        renderTermModal();
        return;
      }
    } catch(e){
      serviceUnavailable = "Wikipedia service unavailable: remote lookup failed. References, idea map, and related library still work.";
    }
  }
  if (serviceUnavailable) {
    glossaryState.wikipediaRemoteUnavailable[keys[0].toLowerCase()] = serviceUnavailable;
    renderTermModal();
    return;
  }
  glossaryState.wikipediaCache[keys[0].toLowerCase()] = { error:true };
  saveWikipediaCache();
  renderTermModal();
}

async function startDonationCheckout() {
  const amount = getRequestedAmount();
  const validationError = validateAmount(amount);
  if (validationError) {
    setDonationError(validationError);
    return;
  }

  const previousText = checkoutBtn.textContent;
  checkoutBtn.disabled = true;
  checkoutBtn.textContent = "Opening Stripe...";
  setDonationError("");

  try {
    if (shouldUseLocalReaderSimulation()) {
      const profile = getDonationProfile();
      const safeSummary = recordLocalReaderPaymentSimulation({ siteId: SITE_ID, amount, profile });
      state.paymentSummaries = { ...(state.paymentSummaries || {}), [SITE_ID]: safeSummary };
      savePaymentSummaries(state.paymentSummaries);
      updatePaymentSummaryStatus();
      closeDonationModal();
      showAlert("Local donation simulated. No Stripe checkout was opened.");
      return;
    }

    const token = await getFirebaseToken();
    const profile = getDonationProfile();
    const headers = { "content-type": "application/json" };
    if (token) headers.Authorization = `Bearer ${token}`;

    const response = await fetch(`${WORKER_BASE_URL}/api/donations/checkout`, {
      method: "POST",
      headers,
      body: JSON.stringify({
        site: SITE_ID,
        amount,
        customerName: profile.name,
        customerEmail: profile.email
      })
    });
    const result = await response.json().catch(() => ({}));

    if (!response.ok) {
      throw new Error(result?.error?.message || "Donation checkout failed");
    }
    if (!result?.url) {
      throw new Error("Donation checkout did not return a Stripe URL.");
    }

    window.location.assign(result.url);
  } catch (error) {
    setDonationError(error.message || "Donation checkout failed.");
    checkoutBtn.disabled = false;
    checkoutBtn.textContent = previousText;
  }
}

async function refreshPaymentSummaryFromWorker(user) {
  if (readerRuntime.isLocalMode) {
    const paymentSummaries = readLocalReaderPaymentSummaries(SITE_ID);
    state.paymentSummaries = { ...(state.paymentSummaries || {}), ...paymentSummaries };
    savePaymentSummaries(state.paymentSummaries);
    updatePaymentSummaryStatus();
    return state.paymentSummaries[SITE_ID] || null;
  }
  if (!user || typeof user.getIdToken !== "function" || !window.firebaseDB) return null;
  try {
    const token = await user.getIdToken();
    const response = await fetch(`${PAYMENTS_WORKER_BASE_URL}/api/me/payment-summary?site=${encodeURIComponent(SITE_ID)}`, {
      headers: { Authorization: `Bearer ${token}` }
    });
    const result = await response.json().catch(() => ({}));
    if (!response.ok) {
      throw new Error(result?.error?.message || "Unable to refresh payment summary.");
    }

    const safeSummary = {
      site: result.site || SITE_ID,
      summary: result.summary || {},
      items: Array.isArray(result.items) ? result.items : [],
      source: result.source || "d1",
      syncedAt: result.syncedAt || new Date().toISOString()
    };
    const paymentSummaries = { ...(state.paymentSummaries || {}), [SITE_ID]: safeSummary };
    state.paymentSummaries = paymentSummaries;
    savePaymentSummaries(paymentSummaries);

    const db = window.firebaseDB;
    const userRef = window.firestoreDoc(db, 'userPrivate', user.uid);
    await window.firestoreSetDoc(userRef, {
      paymentSummaries,
      paymentSummariesSyncedAt: window.firestoreServerTimestamp()
    }, { merge: true });
    return safeSummary;
  } catch (error) {
    console.error('Error refreshing payment summary from Worker:', error);
    return null;
  } finally {
    updatePaymentSummaryStatus();
  }
}

function remoteBookEnrichmentShouldStayLocal(){
  return readerRuntime.isLocalMode || navigator.onLine === false || typeof fetch !== "function";
}

function remoteBookEnrichmentUnavailableHtml(message = ""){
  const reason = message || (
    readerRuntime.isLocalMode
      ? "Remote book details are unavailable in local mode. Your local notes and outside search links still work."
      : "Remote book details are unavailable while offline. Your local notes and outside search links still work."
  );
  return `<div class="bookDetailsError">${escapeHtml(reason)}</div>`;
}

function lookupKeys(term){
  const phrase = term.term.replace(/\s+/g," ").trim();
  const words = phrase.split(/\s+/).filter(w => !/^(and|or|of|the|a|an|to|in)$/i.test(w));
  return Array.from(new Set([phrase, words[0]].filter(Boolean)));
}

function glossaryRemoteEnrichmentUnavailableReason(kind){
  if (readerRuntime.isLocalMode) return `Local mode: ${kind} enrichment needs a remote service. References, idea map, and related library still work.`;
  if (navigator.onLine === false) return `Offline mode: ${kind} enrichment needs the network. References, idea map, and related library still work.`;
  if (typeof fetch !== "function") return `Remote fetch unavailable: ${kind} enrichment cannot load here. References, idea map, and related library still work.`;
  return "";
}

function getRawTermsPayload(data){
  if (Array.isArray(data)) return data;
  if (Array.isArray(data.entries)) return data.entries;
  if (Array.isArray(data.terms)) return data.terms;
  return [];
}

function normalizeTerm(raw){
  const baseTerm = raw.term || raw.title || "Untitled Term";
  const qualifier = raw.qualifier || null;
  const displayTerm = qualifier ? `${baseTerm} (${qualifier})` : baseTerm;
  return {
    id: raw.id || slugify(displayTerm),
    letter: String(raw.letter || baseTerm[0] || "#").toUpperCase(),
    term: baseTerm,
    qualifier,
    displayTerm,
    entry: raw.entry || `${displayTerm}: ${raw.see || ""}`.trim(),
    see: raw.see || null,
    seeAlso: raw.seeAlso || raw.see_also || null,
    search: normalizeText([baseTerm, qualifier, raw.entry, raw.see, raw.seeAlso || raw.see_also].filter(Boolean).join(" "))
  };
}

function parseCsvRecords(text){
  const rows = parseCsvRows(text);
  if (!rows.length) return [];
  const headers = rows[0].map(h => String(h || "").trim());
  return rows.slice(1)
    .filter(row => row.some(cell => String(cell || "").trim()))
    .map(row => Object.fromEntries(headers.map((header, index) => [header, row[index] || ""])));
}

function parseCsvRows(text){
  const rows = [];
  let row = [];
  let cell = "";
  let inQuotes = false;
  const src = String(text || "").replace(/^\uFEFF/, "");
  for (let i = 0; i < src.length; i++){
    const ch = src[i];
    const next = src[i + 1];
    if (inQuotes){
      if (ch === '"' && next === '"'){
        cell += '"';
        i++;
      } else if (ch === '"'){
        inQuotes = false;
      } else {
        cell += ch;
      }
      continue;
    }
    if (ch === '"'){
      inQuotes = true;
    } else if (ch === ","){
      row.push(cell);
      cell = "";
    } else if (ch === "\n"){
      row.push(cell);
      rows.push(row);
      row = [];
      cell = "";
    } else if (ch !== "\r"){
      cell += ch;
    }
  }
  if (cell || row.length){
    row.push(cell);
    rows.push(row);
  }
  return rows;
}

